  const separator = tail && !/^\r?\n/.test(tail) ? "\n" : "";
  const content = tail ? `${generated.trimEnd()}${separator}${tail}` : `${generated.trimEnd()}\n`;
  if (existingContent === content) return;
  await writeTextFileAtomic(root, safePath, content);
